1	//! Agent-facing output: TOON projections of command results and conversion of [`MonoklError`] into michi errors.
2	use std::collections::BTreeMap;
3	
4	use camino::Utf8Path;
5	use michi::toon::Value;
6	
7	use crate::error::MonoklError;
8	use crate::types::{Diagnostic, RankedBlock, SearchResponse};
9	
10	/// Maps `None` to [`Value::Null`], so a reader can tell an absent field from an empty string.
11	fn opt_cell(s: Option<&str>) -> Value {
12	    s.map_or(Value::Null, Value::from)
13	}
14	
15	/// The most snippet lines a row can show, and the largest value `--snippet-lines` takes.
16	pub const MAX_SNIPPET_LINES: usize = 3;
17	/// The snippet lines a row shows unless `--snippet-lines` says otherwise.
18	pub const DEFAULT_SNIPPET_LINES: usize = 1;
19	/// The most characters of one matching line a snippet shows.
20	const SNIPPET_LINE_CHARS: usize = 160;
21	
22	/// How a search response is shown: how long each row's snippet is, and the row cap the truncation hint names.
23	///
24	/// # Examples
25	///
26	/// ```
27	/// use monokl::output::agent::SearchView;
28	///
29	/// let view = SearchView::default();
30	/// assert_eq!((view.snippet_lines, view.max_results), (1, 20));
31	/// ```
32	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
33	pub struct SearchView {
34	    /// The most matching lines a row's snippet shows, from 0 to [`MAX_SNIPPET_LINES`]. With 0 the column is `null` and a
35	    /// variable or type alias row, which has no signature, shows no declaration text.
36	    pub snippet_lines: usize,
37	    /// The row cap the response was budgeted with, which tells the hint whether the rows or the tokens ran out.
38	    pub max_results: usize,
39	}
40	
41	impl Default for SearchView {
42	    fn default() -> Self {
43	        Self { snippet_lines: DEFAULT_SNIPPET_LINES, max_results: crate::budget::Budget::default().max_results }
44	    }
45	}
46	
47	/// The lines of `block` that matched the query, numbered, so a reader often needs no second read of the file.
48	///
49	/// A line the signature column already shows is left out: one whose text lies inside the block's
50	/// [`signature_span`](crate::types::CodeBlock::signature_span). A variable or type alias has no signature, so its first
51	/// line is the best thing to show; so is a first line that says more than the signature, such as a decorator or the
52	/// start of an arrow function's body. At most `max_lines` lines appear, each cut to [`SNIPPET_LINE_CHARS`] characters,
53	/// and the lines beyond that are counted, not dropped silently. With `max_lines` 0 there is no snippet at all.
54	fn snippet(block: &crate::types::CodeBlock, max_lines: usize) -> Option<String> {
55	    let mut lines = Vec::new();
56	    let mut start = block.span.start;
57	    for text in block.code.split('\n') {
58	        lines.push((start, text));
59	        start += text.len() + 1;
60	    }
