12	use clap::{Args, Parser, Subcommand, ValueEnum};
13	
14	use crate::analysis::lang::{Language, TEST_DIRS};
15	use crate::analysis::registry::AnalyzerRegistry;
16	use crate::budget::{Budget, apply_budget};
17	use crate::error::MonoklError;
18	use crate::output::agent::{
19	    DEFAULT_SNIPPET_LINES, MAX_SNIPPET_LINES, SearchView, ToDomainError, render_search, search_row_texts,
20	};
21	use crate::pipeline::{SearchRequest, search_with_timeout};
22	use crate::text_search::DEFAULT_MAX_FILES;
