24	
25	/// AST-aware code search for coding agents.
26	#[derive(Debug, Parser)]
27	#[command(name = "monokl", version, about)]
28	struct Cli {
29	    #[command(subcommand)]
30	    command: Command,
31	}
32	
33	#[derive(Debug, Subcommand)]
34	enum Command {
35	    /// Searches a directory and prints the matching code blocks, best first.
36	    Search(SearchArgs),
37	    /// Prints the file rules of every language as JSON, for the scripts that compare monokl with ripgrep.
38	    #[command(hide = true)]
39	    LanguageRules,
40	}
41	
42	#[derive(Debug, Args)]
43	struct SearchArgs {
44	    /// The query: words, "quoted phrases", `+required`, `-excluded` and `regex:pattern` terms.
45	    query: String,
46	    /// The directory to search.
47	    #[arg(default_value = ".")]
48	    path: Utf8PathBuf,
49	    /// Treats the whole query as one literal term.
50	    #[arg(long)]
51	    exact: bool,
52	    /// Searches test files too.
53	    #[arg(long)]
54	    tests: bool,
55	    /// Searches hidden files and files that .gitignore or .ignore (in the search path or its parents) would exclude.
56	    #[arg(long)]
57	    no_ignore: bool,
58	    /// Searches only this language: typescript, javascript or rust.
59	    #[arg(long, value_enum)]
60	    language: Option<Language>,
61	    /// The most results to print. It also caps the rows `--min-score` keeps, so it can cut below the first eight.
