        ] {
            let arg = format!("{flag}={value}");
            let (code, out, err) = run_args(&["search", "alpha", &arg]);
            assert_eq!(code, ExitCode::from(2), "{arg}");
            assert_eq!(out, "", "{arg}");
            assert!(err.contains(&format!("invalid value '{value}' for '{flag} <")), "{arg}: {err}");
